def longest_repeated_substring(L, S):
    for length in range(L, 0, -1):
        for i in range(L - length + 1):
            substring = S[i:i + length]
            for j in range(L - length + 1):
                if i != j and S[j:j + length] == substring:
                    return length
    return 0

